<script setup lang="ts">
import {computed,ref,reactive,watch} from 'vue'
import {RefreshCwIcon,MonitorIcon,NetworkIcon,RouteIcon,ContainerIcon,ScrollTextIcon,ShieldCheckIcon,AlertCircleIcon} from '@lucide/vue'
import {Button} from '@/components/ui/button'
import {Input} from '@/components/ui/input'
import {Field,FieldLabel,FieldGroup,FieldDescription} from '@/components/ui/field'
import {Alert,AlertTitle,AlertDescription} from '@/components/ui/alert'
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription,DialogFooter} from '@/components/ui/dialog'
import DataTable from './DataTable.vue'
import AppSelect from './AppSelect.vue'
import VmPicker from './VmPicker.vue'
import {state,guest,guestArgs,guestReady,run,refreshVms,refreshHost,refreshServices,serviceId,changeService} from '@/lib/store'
import {native} from '@/lib/bridge'
const names:Record<string,string>={overview:'网络概览',network:'网卡与设备',routes:'默认出口与路由',vpn:'VPN 连接',containers:'容器状态',services:'运行与日志'}
const icon=computed(()=>({overview:MonitorIcon,network:NetworkIcon,routes:RouteIcon,vpn:ShieldCheckIcon,containers:ContainerIcon,services:ScrollTextIcon}[state.page as 'overview']))
const data=ref<any>(null);const plan=ref<any>(null);const planType=ref('host');const dialog=ref(false);const previewArgs=ref<string[]>([]);let generation=0
const form=reactive({device:'',mode:'shared',iface:'',usb:'',interface:'',gateway:'',destination:'',lookup:'',vpn:''})
const adapters=computed(()=>Object.entries(guest()?.Hardware||{}).filter(([k])=>/^net\d+$/.test(k)).map(([name,a]:[string,any])=>({name,...a})))
const rows=computed(()=>state.vms.map(v=>({...v,status:v.State==='running'?'运行中':v.State==='suspended'?'已挂起':'已停止',tools:v.GuestTools?.state||'未知',ips:(v.Network?.ipAddresses||[]).filter(i=>i.type==='ipv4').map(i=>i.ip).join(', ')})))
const serviceRows=computed(()=>[...state.mac,...state.guest].map(r=>({...r,endpoint:`${r.ip}:${r.port}`,where:r.location==='host'?'本地 Mac':guest()?.Name||'虚拟机',statusLabel:r.running?'运行中':'已停止',active:r.stats?.active??'—'})))
async function load(){const id=++generation;data.value=null;try{let result;if(state.page==='network'){await refreshHost();return}if(state.page==='services'){await refreshServices();return}if(!guestReady())return;if(state.page==='routes')result=await run('cli',guestArgs('routes','list'));if(state.page==='containers')result=await run('cli',guestArgs('containers','list'));if(state.page==='vpn')result=await run('cli',guestArgs('vpn','list'));if(id===generation)data.value=result}catch{}}
watch(()=>[state.page,state.vm],()=>{plan.value=null;dialog.value=false;void load()},{immediate:true})
async function netPreview(op:string){try{plan.value=await run('host-preview',[JSON.stringify({vm:state.vm,op,device:op.startsWith('usb-')?form.usb:form.device,mode:form.mode,iface:form.iface})]);planType.value='host';dialog.value=true}catch{}}
async function routePreview(op:string){try{plan.value=await run('cli',guestArgs('routes','preview','--request',JSON.stringify({op,interface:form.interface,gateway:form.gateway,destination:form.destination})));planType.value='routes';dialog.value=true}catch{}}
async function apply(){try{if(planType.value==='host')await run('host-apply',[JSON.stringify(plan.value)]);else if(planType.value==='routes')await run('cli',guestArgs('routes','apply','--request',JSON.stringify(plan.value)));else if(planType.value==='rollback')await run('cli',guestArgs('routes','rollback'));else await run('cli',previewArgs.value);dialog.value=false;await load()}catch{dialog.value=false}}
async function vpnPreview(op:string){try{previewArgs.value=guestArgs('vpn',op,'--name',form.vpn);const text=await run('cli',[...previewArgs.value,'--dry-run']);plan.value={description:`${op==='connect'?'连接':'断开'} ${form.vpn}`,note:'使用虚拟机已有配置和已保存凭据。',details:text};planType.value='cli';dialog.value=true}catch{}}
async function lookup(){try{const r=await run('cli',guestArgs('routes','lookup','--request',JSON.stringify({ip:form.lookup})));state.output=r.result||JSON.stringify(r)}catch{}}
function chooseVM(row:any){state.vm=row.ID}
function viewLog(row:any){state.selectedRule=serviceId(row);state.page=row.kind==='socks'?'socks':'forward'}
</script>
<template>
 <section class="flex h-full flex-col overflow-y-auto p-6">
  <div class="mb-5 flex items-center justify-between"><h1 class="flex items-center gap-2.5 text-lg font-semibold"><component :is="icon" class="size-5"/>{{names[state.page]}}</h1><Button variant="outline" :disabled="!!state.pending" @click="state.page==='overview'?refreshVms():load()"><RefreshCwIcon data-icon="inline-start"/>刷新</Button></div>
  <Alert v-if="state.error" variant="destructive" class="mb-5"><AlertCircleIcon/><AlertTitle>操作未完成</AlertTitle><AlertDescription>{{state.error}}</AlertDescription></Alert>
  <div v-if="state.page!=='overview'&&state.page!=='services'" class="mb-6 flex max-w-[580px] items-center gap-4"><label class="shrink-0 text-sm">所选虚拟机</label><VmPicker/></div>
  <template v-if="state.page==='overview'">
   <p class="mb-5 text-sm text-muted-foreground">运行状态来自 Parallels。选择虚拟机后，可管理它的网络、转发与路由。</p>
   <div class="rounded-md border"><DataTable :rows="rows" :columns="[{key:'Name',label:'虚拟机名称'},{key:'OS',label:'系统'},{key:'status',label:'运行状态'},{key:'tools',label:'Parallels Tools'},{key:'ips',label:'IPv4'}]" clickable @choose="chooseVM"/></div>
   <div class="mt-5 flex gap-2"><Button variant="outline" :disabled="!guestReady()||!!state.pending" @click="run('cli',guestArgs('status')).catch(()=>{})">读取所选虚拟机状态</Button><Button variant="outline" :disabled="!state.vm" @click="state.page='network'">管理网络</Button></div>
  </template>
  <template v-else-if="state.page==='network'">
   <h2 class="mb-3 font-medium">Mac 网卡与设备</h2><div class="mb-6 rounded-md border"><DataTable :rows="(state.host?.interfaces||[]).map((i:any)=>({...i,ips:i.ips?.join(', ')}))" :columns="[{key:'device',label:'Mac 接口'},{key:'name',label:'设备名称'},{key:'state',label:'链路'},{key:'ips',label:'IPv4'}]"/></div>
   <h2 class="mb-3 font-medium">虚拟机网卡</h2><div class="mb-6 rounded-md border"><DataTable :rows="adapters" :columns="[{key:'name',label:'网卡'},{key:'type',label:'网络模式'},{key:'iface',label:'桥接接口'},{key:'enabled',label:'启用'},{key:'state',label:'连接状态'}]"/></div>
   <FieldGroup class="max-w-[580px]"><div class="grid grid-cols-2 gap-5"><Field><FieldLabel>要修改的网卡</FieldLabel><AppSelect v-model="form.device" :options="adapters.map(a=>({value:a.name,label:a.name}))" placeholder="选择网卡"/></Field><Field><FieldLabel>网络模式</FieldLabel><AppSelect v-model="form.mode" :options="[{value:'shared',label:'共享网络（NAT）'},{value:'bridged',label:'桥接网络'},{value:'host-only',label:'仅主机网络'}]"/></Field></div><Field v-if="form.mode==='bridged'"><FieldLabel>桥接到 Mac 网卡</FieldLabel><AppSelect v-model="form.iface" :options="(state.host?.networks||[]).filter((n:any)=>n.Type==='bridged'&&n['Bound To']!=='FF:FF:FF:FF:FF:FF').map((n:any)=>({value:n['Bound To'],label:`${n['Network ID']} · ${n['Bound To']}`}))"/></Field></FieldGroup>
   <div class="my-4 flex flex-wrap gap-2"><Button :disabled="!state.vm||!form.device||!!state.pending||!native" @click="netPreview('mode')">预览修改模式</Button><Button variant="outline" :disabled="!state.vm||!!state.pending||!native" @click="netPreview('add')">预览新增网卡</Button><Button v-for="(label,op) in {connect:'连接网线',disconnect:'断开网线',enable:'启用网卡',disable:'禁用网卡'}" :key="op" variant="outline" :disabled="!form.device||!!state.pending||!native" @click="netPreview(op)">{{label}}</Button></div>
   <p class="subtle">共享网络使用 Mac 当前出口。桥接通过指定物理接口入网；应用前会重新核对配置。</p>
   <div class="mt-7 border-t pt-5"><h2 class="mb-4 font-medium">USB 设备归属 / 独占直通</h2><Field class="max-w-[580px]"><FieldLabel>USB 设备</FieldLabel><AppSelect v-model="form.usb" :options="(state.host?.usb||[]).map((u:any)=>({value:u['System name'],label:`${u.Name} · ${u['Present-On-Host']==='YES'?'已插入':'未插入'}`}))"/></Field><div class="my-4 flex flex-wrap gap-2"><Button v-for="(label,op) in {'usb-connect':'连接到所选虚拟机','usb-disconnect':'从所选虚拟机释放','usb-assign':'记住归属到虚拟机','usb-host':'下次归属 Mac','usb-ask':'下次插入询问'}" :key="op" variant="outline" :disabled="!state.vm||!form.usb||!!state.pending||!native" @click="netPreview(op)">{{label}}</Button></div><p class="subtle">USB 直通由一台虚拟机独占，Mac 无法同时使用。写操作均先预览。</p></div>
  </template>
  <template v-else-if="state.page==='routes'">
   <p v-if="!guestReady()" class="subtle">请先选择运行中的虚拟机。</p><template v-else>
    <div class="mb-6 rounded-md border"><DataTable :rows="data?.routes||[]" :columns="[{key:'destination',label:'目标网段'},{key:'gateway',label:'网关'},{key:'interface',label:'出口网卡'},{key:'metric',label:'Metric'},{key:'protocol',label:'协议'}]"/></div>
    <FieldGroup class="max-w-[580px]"><Field><FieldLabel>出口网卡</FieldLabel><AppSelect v-model="form.interface" :options="(data?.interfaces||[]).filter((i:any)=>i.ips?.length&&!['lo','lo0'].includes(i.id)).map((i:any)=>({value:i.id,label:`${i.name} · ${i.ips.join(', ')}`}))"/></Field><Field><FieldLabel>下一跳网关</FieldLabel><Input v-model="form.gateway" placeholder="必须可从所选网卡直连；直连目标可留空"/></Field><div><Button :disabled="!form.interface||!form.gateway||!!state.pending||!native" @click="routePreview('default')">预览设为默认 IPv4 出口</Button></div><Field><FieldLabel>指定 IP / 网段</FieldLabel><Input v-model="form.destination" placeholder="填写单个 IPv4 或 IPv4/CIDR"/></Field><div class="flex gap-2"><Button variant="outline" :disabled="!form.interface||!form.destination||!!state.pending||!native" @click="routePreview('add')">预览添加路由</Button><Button variant="outline" :disabled="!form.destination||!!state.pending||!native" @click="routePreview('delete')">预览删除路由</Button></div><Field><FieldLabel>查询实际出口（不发送探测包）</FieldLabel><div class="flex gap-2"><Input v-model="form.lookup" placeholder="目标 IPv4"/><Button variant="outline" :disabled="!form.lookup||!!state.pending" @click="lookup">查询出口</Button></div></Field></FieldGroup>
    <Button v-if="data?.can_rollback" class="mt-5 w-fit" variant="outline" :disabled="!!state.pending||!native" @click="plan={description:'撤销上次路由变更',note:'若路由已被其他程序修改，将拒绝自动撤销。'};planType='rollback';dialog=true">撤销上次路由变更…</Button><p class="subtle mt-4">仅当前会话生效，不修改 DNS、IPv6 和持久化网络配置；VPN/DHCP 重连可能覆盖。</p>
   </template>
  </template>
  <template v-else-if="state.page==='containers'"><p class="subtle mb-4">读取所选虚拟机的 Docker / Podman，不会启动容器或引擎。</p><Alert v-for="(e,i) in data?.errors||[]" :key="i" class="mb-3"><AlertDescription>{{e}}</AlertDescription></Alert><div class="rounded-md border"><DataTable :rows="data?.containers||[]" :columns="[{key:'engine',label:'引擎'},{key:'name',label:'容器名称'},{key:'image',label:'镜像'},{key:'status',label:'状态'},{key:'ports',label:'端口'}]"/></div></template>
  <template v-else-if="state.page==='vpn'"><p class="subtle mb-5">连接所选虚拟机中已有的 VPN 配置，使用已保存凭据。</p><pre class="mb-6 rounded-md border bg-muted/20 p-4">{{typeof data==='string'?data:JSON.stringify(data,null,2)}}</pre><FieldGroup class="max-w-[520px]"><Field><FieldLabel>已有 VPN 连接名称</FieldLabel><Input v-model="form.vpn" placeholder="填写虚拟机中的连接名称"/></Field><div class="flex gap-2"><Button :disabled="!form.vpn||!guestReady()||!!state.pending||!native" @click="vpnPreview('connect')">预览连接</Button><Button variant="outline" :disabled="!form.vpn||!guestReady()||!!state.pending||!native" @click="vpnPreview('disconnect')">预览断开</Button></div></FieldGroup></template>
  <template v-else-if="state.page==='services'"><div class="mb-5 flex max-w-[580px] items-center gap-3"><label class="shrink-0">虚拟机规则来源</label><VmPicker optional/></div><p class="subtle mb-4">Mac 本地规则 + 所选虚拟机规则。点击日志可查看完整连接记录。</p><div class="rounded-md border"><DataTable :rows="serviceRows" :columns="[{key:'statusLabel',label:'状态'},{key:'kind',label:'类型'},{key:'endpoint',label:'访问入口'},{key:'where',label:'运行位置'},{key:'target',label:'实际目标'},{key:'active',label:'连接'}]"><template #actions="{row}"><div class="flex gap-1"><Button variant="ghost" size="sm" @click="viewLog(row)">日志</Button><Button variant="outline" size="sm" :disabled="!!state.pending||!native||!row.managed" @click="changeService(row,row.running?'stop':'start')">{{row.running?'停止':'开启'}}</Button></div></template></DataTable></div></template>
  <details v-if="state.output" class="mt-6 text-xs text-muted-foreground"><summary>执行详情</summary><pre class="mt-3 rounded-md border p-4">{{state.output}}</pre></details>
  <Dialog v-model:open="dialog"><DialogContent class="max-h-[80vh] overflow-y-auto sm:max-w-[650px]"><DialogHeader><DialogTitle>配置预览</DialogTitle><DialogDescription>{{plan?.description||'核对即将应用的配置'}}</DialogDescription></DialogHeader><p class="subtle">{{plan?.note}}</p><template v-if="planType==='routes'"><h3 class="font-medium">变更前</h3><pre>{{JSON.stringify(plan?.before,null,2)}}</pre><h3 class="font-medium">变更后</h3><pre>{{JSON.stringify(plan?.after,null,2)}}</pre></template><pre v-else>{{plan?.details||plan?.args?.join(' ')||JSON.stringify(plan?.request,null,2)}}</pre><DialogFooter><Button variant="outline" @click="dialog=false">取消</Button><Button :disabled="!!state.pending||!native" @click="apply">应用这份配置</Button></DialogFooter></DialogContent></Dialog>
 </section>
</template>
